INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('3a45765b-ee4b-46fe-85cb-a74d472cac4c', 'ffa9985f-5a70-47fe-a100-cb9e0d8d1d87', 'A 62-year-old female patient A mother asks for advice regarding her 4-year-old child who has a severe atopic eczema flare on the face and flexural folds. She has tubes of Clobetasol propionate, Betamethasone valerate, and Hydrocortisone 1%. (Case Ref: DERMATOLOGY-1401). Relevant physiological and medication history have been reviewed.', 'Which topical steroid is safe and appropriate for short-term application to the facial flare?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a7d27640-8150-48a2-a69b-d19e5fd10283', 'ffa9985f-5a70-47fe-a100-cb9e0d8d1d87', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('960765a7-ed4b-438e-95df-09913ce0ef89', 'ffa9985f-5a70-47fe-a100-cb9e0d8d1d87', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cdba8fa7-fca7-444b-af1b-6fb93f269b23', 'ffa9985f-5a70-47fe-a100-cb9e0d8d1d87', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('93334653-d25c-40d7-aa10-308ee9f3b456', 'ffa9985f-5a70-47fe-a100-cb9e0d8d1d87', 'D', 'Mix topical steroid 50:50 with liquid paraffin in the dispensing tub', 0, 'Deprecated historical practice. Diluting steroids leads to unpredictable stability and microbial contamination.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e22b1947-df8f-4685-9710-89dacf589de8', 'ffa9985f-5a70-47fe-a100-cb9e0d8d1d87', 'E', 'Apply emollient simultaneously without leaving a 20-30 minute interval', 0, 'Incorrect technique. Applying emollient at the exact same moment dilutes the active steroid and spreads it to unaffected skin.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('1d73dc33-c40a-4ac5-a64b-b0a32c9375fe', 'ffa9985f-5a70-47fe-a100-cb9e0d8d1d87', 'Use mild corticosteroids (Hydrocortisone 1%) for face and flexures. Allow 20-30 minutes between steroid and emollient.', 'One Fingertip Unit (FTU) is approximately 0.5 g and covers the area of two adult palms. Reference: NICE CG57 & BNF Chapter 13.', 'NICE CG57 & BNF Chapter 13', 1789655696, 1789655696);
