INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'ACP-Q-1406', 1, 'published', 'p-mpharm', 'sub-bph', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('e5fe1fa2-901d-4efe-a76d-a500b49b3627', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'A 22-year-old female patient A 22-year-old female requests emergency contraception 80 hours after unprotected sexual intercourse. She takes Carbamazepine for focal seizures and has a BMI of 27. (Case Ref: GENITO-URINARY-1406). Relevant physiological and medication history have been reviewed.', 'What is the most effective and appropriate emergency contraceptive method?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a9d6ceab-4f49-444e-a045-44c65f0cad3d', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e1d2da9a-6461-494c-a63c-6d8107ee0c50', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8d1e8270-e855-44b5-b623-10878510f1f1', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('db3ccb38-7b22-452e-baca-ad915e2f1bc2', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('84cc0f45-f514-4c95-8790-5d68ee6f4e98', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
