INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('1f6e71f2-9e4d-4276-b9c5-8a3eead74a38', 'f1272df5-705f-4d41-b614-cb5f89be3d36', 'A 23-year-old female patient A 22-year-old female requests emergency contraception 80 hours after unprotected sexual intercourse. She takes Carbamazepine for focal seizures and has a BMI of 27. (Case Ref: GENITO-URINARY-1434). Relevant physiological and medication history have been reviewed.', 'What is the most effective and appropriate emergency contraceptive method?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ce7239ec-806b-4f85-bd9c-5d7fed170a79', 'f1272df5-705f-4d41-b614-cb5f89be3d36', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bf164357-69d8-4fb6-8e1d-fa0fada04ee8', 'f1272df5-705f-4d41-b614-cb5f89be3d36', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f43eed31-15e4-4bad-94de-eab3c5543608', 'f1272df5-705f-4d41-b614-cb5f89be3d36', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('345387bb-a6c3-4e68-b922-1b4ab067c209', 'f1272df5-705f-4d41-b614-cb5f89be3d36', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f8756a3f-6401-4e91-8ee5-0d684d5f5499', 'f1272df5-705f-4d41-b614-cb5f89be3d36', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('7dda62b1-383e-4761-854c-cee98f7f6194', 'f1272df5-705f-4d41-b614-cb5f89be3d36', 'Enzyme inducers require double-dose Levonorgestrel (3 mg) or Cu-IUD. Ulipristal is not recommended with enzyme inducers.', 'Cu-IUD is >99% effective and independent of body weight, BMI, or enzyme induction. Reference: FSRH Clinical Guideline: Emergency Contraception.', 'FSRH Clinical Guideline: Emergency Contraception', 1789655696, 1789655696);
