INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('39d1032d-84ae-4394-88cc-547af2013993', 'fd149443-2104-424d-9a63-dbc5d8c57a98', 'A 35-year-old male patient A 22-year-old female requests emergency contraception 80 hours after unprotected sexual intercourse. She takes Carbamazepine for focal seizures and has a BMI of 27. (Case Ref: GENITO-URINARY-1445). Relevant physiological and medication history have been reviewed.', 'What is the most effective and appropriate emergency contraceptive method?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8befa08a-447f-40db-b70b-509edfa64bbd', 'fd149443-2104-424d-9a63-dbc5d8c57a98', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b835c14f-8307-46fd-a829-74b618462dc1', 'fd149443-2104-424d-9a63-dbc5d8c57a98', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4e0c2124-a26c-4541-9bd0-2c8d142e2e25', 'fd149443-2104-424d-9a63-dbc5d8c57a98', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7c97c52b-0f32-4d44-9d1b-e67cc4738f57', 'fd149443-2104-424d-9a63-dbc5d8c57a98', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2efcf340-4ff2-4986-9e77-c37527537e9d', 'fd149443-2104-424d-9a63-dbc5d8c57a98', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ca766499-3c96-4a86-9a81-94d606f6a297', 'fd149443-2104-424d-9a63-dbc5d8c57a98', 'Enzyme inducers require double-dose Levonorgestrel (3 mg) or Cu-IUD. Ulipristal is not recommended with enzyme inducers.', 'Cu-IUD is >99% effective and independent of body weight, BMI, or enzyme induction. Reference: FSRH Clinical Guideline: Emergency Contraception.', 'FSRH Clinical Guideline: Emergency Contraception', 1789655696, 1789655696);
