INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cf8e81f7-54ec-4c51-82ae-4031e43c1fa1', '3ae28417-e9fb-4435-9c75-12b49e4526dd', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ae3f4839-adae-484f-9837-8881846c5d18', '3ae28417-e9fb-4435-9c75-12b49e4526dd', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
