INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('dff995bb-1406-4bbf-88e2-fc43fcd8c8d6', 'f33ad8ee-6532-409f-bdc2-745a4613d6fa', 'A 41-year-old male patient A 22-year-old female requests emergency contraception 80 hours after unprotected sexual intercourse. She takes Carbamazepine for focal seizures and has a BMI of 27. (Case Ref: GENITO-URINARY-1483). Relevant physiological and medication history have been reviewed.', 'What is the most effective and appropriate emergency contraceptive method?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6d202c5e-a41c-48eb-a0d9-cf7acb6b12a6', 'f33ad8ee-6532-409f-bdc2-745a4613d6fa', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cd8896e7-229c-4ea9-a915-28509c32df47', 'f33ad8ee-6532-409f-bdc2-745a4613d6fa', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a12a3067-48ca-470a-98e0-bae8779ad8c6', 'f33ad8ee-6532-409f-bdc2-745a4613d6fa', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('83dcd2b2-bc55-4d36-b47d-e02676d34e7f', 'f33ad8ee-6532-409f-bdc2-745a4613d6fa', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e28872f7-fa3a-4eb3-9d42-5d0631ccea47', 'f33ad8ee-6532-409f-bdc2-745a4613d6fa', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
