INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('2917e077-fd73-47e5-8cf4-40c32bf25e54', 'ACP-Q-1486', 1, 'published', 'p-mpharm', 'sub-oral-chemo', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('32e955a6-423c-4631-a903-ae3f8d26b5af', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'A 22-year-old female patient A 50-year-old patient undergoing systemic cytotoxic chemotherapy for breast cancer attends community pharmacy with a temperature of 38.3°C and shivering, but feels otherwise relatively well. (Case Ref: MALIGNANCY-1486). Relevant physiological and medication history have been reviewed.', 'What is the immediate and mandatory course of action?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('410fccaa-830c-4f4f-80eb-a155e729fa97', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'A', 'Direct the patient immediately to the emergency oncology assessment unit or hospital A&E for urgent IV broad-spectrum antibiotics within 1 hour', 1, 'Correct. Febrile neutropenia is a medical emergency with mortality risk from septic shock. Empirical IV antibiotics (e.g. piperacillin-tazobactam) must be administered within 60 minutes of arrival.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('04289a17-aa1f-44c6-869d-7ce8f4be72d8', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ad7dbadc-89e3-4faa-9ee5-93d7d7109a13', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('35bac50c-8f2f-47c3-a226-eb1a48125418', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'D', 'Wait for blood culture and full blood count results before initiating antimicrobial therapy', 0, 'Deprecated historical practice. "Door-to-needle" time must be < 1 hour without waiting for lab confirmation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4f08e495-0bb5-42fb-8c3b-59efb3767af0', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'E', 'Reassure patient that mild fever is expected after chemotherapy', 0, 'Extremely negligent. Any fever >= 38.0°C in a chemotherapy patient within 4 weeks of treatment must be treated as neutropenic sepsis until proven otherwise.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('65d13102-e9a1-4310-87f7-4dce3f328f85', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'Chemotherapy fever >= 38°C is an emergency. Urgent hospital referral for IV antibiotics within 1 hour is life-saving.', 'Defined as neutrophil count <= 0.5 x 10^9/L with fever >= 38°C or clinical sepsis. Reference: NICE CG151: Neutropenic sepsis: prevention and management.', 'NICE CG151: Neutropenic sepsis: prevention and management', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('6cd58832-9f33-409c-ba01-3ba827ccc3d5', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
