INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e895c5f2-a000-4f97-b8dd-8536247b3c5a', 'cfcc37f9-bc99-4f60-849a-4af7ec5e4568', 'A', 'Direct the patient immediately to the emergency oncology assessment unit or hospital A&E for urgent IV broad-spectrum antibiotics within 1 hour', 1, 'Correct. Febrile neutropenia is a medical emergency with mortality risk from septic shock. Empirical IV antibiotics (e.g. piperacillin-tazobactam) must be administered within 60 minutes of arrival.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b065ea56-505e-4afd-b0d1-0aef6452090f', 'cfcc37f9-bc99-4f60-849a-4af7ec5e4568', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5de2ed2d-d7e3-407e-ae07-84ae792a568a', 'cfcc37f9-bc99-4f60-849a-4af7ec5e4568', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
