INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3dd637de-2329-4fc6-b27e-422ba5efd4c1', '479ec378-2575-4063-8b27-d2ccf1729b05', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8b11546c-5a43-4667-b860-b0534d524e75', '479ec378-2575-4063-8b27-d2ccf1729b05', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0a72cbec-52c8-4c62-b704-7ce787ee83d7', '479ec378-2575-4063-8b27-d2ccf1729b05', 'D', 'Wait for blood culture and full blood count results before initiating antimicrobial therapy', 0, 'Deprecated historical practice. "Door-to-needle" time must be < 1 hour without waiting for lab confirmation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a38a508e-4622-4eaf-9383-63b6e00592fb', '479ec378-2575-4063-8b27-d2ccf1729b05', 'E', 'Reassure patient that mild fever is expected after chemotherapy', 0, 'Extremely negligent. Any fever >= 38.0°C in a chemotherapy patient within 4 weeks of treatment must be treated as neutropenic sepsis until proven otherwise.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('7a05ca66-aab6-435d-8ced-03918862e8f8', '479ec378-2575-4063-8b27-d2ccf1729b05', 'Chemotherapy fever >= 38°C is an emergency. Urgent hospital referral for IV antibiotics within 1 hour is life-saving.', 'Defined as neutrophil count <= 0.5 x 10^9/L with fever >= 38°C or clinical sepsis. Reference: NICE CG151: Neutropenic sepsis: prevention and management.', 'NICE CG151: Neutropenic sepsis: prevention and management', 1789655696, 1789655696);
