INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('10de64b5-2fa6-46fa-96db-b559b478c8ce', '598c492c-6036-47d0-9b33-28c6d246b4cb', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e11de225-6e50-4756-ab9e-ad741ed39f2e', '598c492c-6036-47d0-9b33-28c6d246b4cb', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
