INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('52273cf6-06b6-431d-afd1-52a24ff18e37', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8603bf3c-6a22-4315-8a50-be5162a0a41c', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'D', 'Wait for blood culture and full blood count results before initiating antimicrobial therapy', 0, 'Deprecated historical practice. "Door-to-needle" time must be < 1 hour without waiting for lab confirmation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('685070f9-45cd-4df9-b622-b32b53962ef2', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'E', 'Reassure patient that mild fever is expected after chemotherapy', 0, 'Extremely negligent. Any fever >= 38.0°C in a chemotherapy patient within 4 weeks of treatment must be treated as neutropenic sepsis until proven otherwise.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('193ab480-6110-4527-aa68-bcab225b5d1c', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'Chemotherapy fever >= 38°C is an emergency. Urgent hospital referral for IV antibiotics within 1 hour is life-saving.', 'Defined as neutrophil count <= 0.5 x 10^9/L with fever >= 38°C or clinical sepsis. Reference: NICE CG151: Neutropenic sepsis: prevention and management.', 'NICE CG151: Neutropenic sepsis: prevention and management', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('81ecc9f6-eb1f-40c5-b696-6c26f593893d', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('3b106a30-69ee-4230-85e6-b02c36b7668c', 'ACP-Q-1561', 1, 'published', 'p-mpharm', 'sub-anaemia', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('50dc8248-73e0-4569-acb8-ec5869a8d96e', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'A 22-year-old female patient A 35-year-old female with microcytic hypochromic anaemia is prescribed Ferrous sulfate 200 mg tablets (65 mg elemental iron). She complains of severe constipation and nausea when taking it three times daily. (Case Ref: BLOOD-NUTRITION-1561). Relevant physiological and medication history have been reviewed.', 'What evidence-based modification improves tolerance and maintains iron absorption?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('20e9f1f7-f212-467f-b450-9d63f4e03ab2', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d1daa59a-b993-40a1-8395-f61b7b8ed06f', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c5a1cbf9-dade-4260-983c-1af64f36d691', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fde35dda-b961-4aea-a0c4-382f87256887', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'D', 'Prescribe high-dose oral iron 200 mg four times daily', 0, 'Deprecated. High doses stimulate hepcidin and block subsequent iron transport, maximizing nausea without therapeutic gain.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b89bb1c3-28c3-4240-9ca6-54adcdc4e822', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'E', 'Check ferritin and haemoglobin 48 hours after starting iron therapy', 0, 'Inappropriate timing. Reticulocytosis takes 5-7 days; significant Hb rise takes 2 to 4 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('2e558392-85e8-4580-801d-90a2fa24df57', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'Alternate-day or once-daily oral iron improves absorption and GI tolerance. Avoid modified-release iron preparations.', 'Target rise in haemoglobin is approximately 2 g/100 mL every 3 to 4 weeks. Reference: BNF Section 9.1.1 & British Society of Gastroenterology.', 'BNF Section 9.1.1 & British Society of Gastroenterology', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('2212fec4-4cca-47f1-a958-df2451576ed4', '3b106a30-69ee-4230-85e6-b02c36b7668c', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
