INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('38742f27-04ba-4e75-a6ec-df21001b79a6', '655b8881-6e0b-42c6-a6d2-0b0e8cd17688', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789655696);
