INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('73cb20a8-6ab4-4971-bd43-84da8cd6f17d', '6cef6de1-43ca-432d-97fa-1301b9be79f9', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('57d35529-25f3-4de9-8faf-b7a5652084d7', '6cef6de1-43ca-432d-97fa-1301b9be79f9', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ba7267d6-5fef-4cb4-af1f-e5ad8b6a49f4', '6cef6de1-43ca-432d-97fa-1301b9be79f9', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789655696);
