INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6b960d17-d412-4152-b683-0a51f50c9c6f', 'bc9ea6e2-d1b0-49a4-b5fc-2c740a23aab2', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f5be2c89-084e-4ffa-954c-9b4bb01c34a1', 'bc9ea6e2-d1b0-49a4-b5fc-2c740a23aab2', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('aff2b7f5-5ba4-4a6c-a102-6494e017f5ef', 'bc9ea6e2-d1b0-49a4-b5fc-2c740a23aab2', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4f23d57e-2b98-45aa-8472-d19964c633b9', 'bc9ea6e2-d1b0-49a4-b5fc-2c740a23aab2', 'D', 'Prescribe high-dose oral iron 200 mg four times daily', 0, 'Deprecated. High doses stimulate hepcidin and block subsequent iron transport, maximizing nausea without therapeutic gain.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('70d986dd-5298-4188-862d-6fce41ad5b16', 'bc9ea6e2-d1b0-49a4-b5fc-2c740a23aab2', 'E', 'Check ferritin and haemoglobin 48 hours after starting iron therapy', 0, 'Inappropriate timing. Reticulocytosis takes 5-7 days; significant Hb rise takes 2 to 4 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('88f93d1f-61fa-4873-bb36-e1e82afdb6e5', 'bc9ea6e2-d1b0-49a4-b5fc-2c740a23aab2', 'Alternate-day or once-daily oral iron improves absorption and GI tolerance. Avoid modified-release iron preparations.', 'Target rise in haemoglobin is approximately 2 g/100 mL every 3 to 4 weeks. Reference: BNF Section 9.1.1 & British Society of Gastroenterology.', 'BNF Section 9.1.1 & British Society of Gastroenterology', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('dbaac3dd-52c5-4b42-9d67-081f5fcfa212', 'bc9ea6e2-d1b0-49a4-b5fc-2c740a23aab2', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
